/** The example as published (guide, full prompt, "Copy example JSON"): sources in the documented form ("generate"). */
export const exampleStoryboardJson = () => storyDocJson(EXAMPLE_STORYBOARD);

/** Preset kinds a storyboard can name, in guide order, with where each id goes. Stickers are not storyboard fields. */
export const GUIDE_KINDS: { kind: PresetKind; title: string; usedIn: string }[] = [
  { kind: "textStyle", title: "Text styles", usedIn: `shots[].layers[].textStyle (default "plain")` },
  { kind: "effect", title: "Text effects", usedIn: `shots[].layers[].style.effect and meta.textStyles[].effect, coloured by "effectColor" (default "none")` },
  { kind: "textAnimIn", title: "Text animations in", usedIn: "shots[].layers[].anim.in" },
  { kind: "textAnimOut", title: "Text animations out", usedIn: "shots[].layers[].anim.out" },
  { kind: "textAnimLoop", title: "Text loops", usedIn: "shots[].layers[].anim.loop" },
  { kind: "videoEffect", title: "Video effects", usedIn: "shots[].effects[].preset" },
  { kind: "blend", title: "Blend modes", usedIn: `shots[].layers[].blend (default "normal"), with "opacity" 0-1 (default 1)` },
  { kind: "audioFx", title: "Audio effects", usedIn: `audio[].fx.preset, with "amount" 0-1 (default 1)` },
  { kind: "transition", title: "Transitions", usedIn: `connections[].transition.preset (params.durationSec, default ${DEFAULT_TRANSITION_SEC})` },
];

const num = (n: number) => String(Math.round(n * 1000) / 1000);
export function paramText(p: ParamSpec): string {
  const base = p.type === "number" ? `${p.key} ${num(p.min)}–${num(p.max)}, default ${num(p.default)}` : p.type === "select" ? `${p.key} one of ${p.options.map((o) => JSON.stringify(o)).join(" | ")}, default ${JSON.stringify(p.default)}` : `${p.key} (${p.type}), default ${JSON.stringify(p.default)}`;
  return p.description ? `${base} (${p.description.replace(/\.$/, "")})` : base;
}
/** The look of a textStyle preset in a few words (font, colour, size), from its `data`. */
function styleLook(d: PresetDescriptor): string {
  const data = d.data ?? {};
  const bits = [typeof data.font === "string" ? `font ${data.font}` : "", typeof data.color === "string" ? `colour ${data.color}` : "", typeof data.size === "number" ? `size ${num(data.size)}` : ""].filter(Boolean);
  return bits.length ? ` Look: ${bits.join(", ")}.` : "";
}
/** The descriptor's optional planner hints (V2-FX-MOD `ai`): when to use it, when not to, example params. */
function aiHints(d: PresetDescriptor): string {
  const a = d.ai;
  if (!a) return "";
  const dot = (t: string) => t.replace(/\.?$/, ".");
  return [a.use ? ` Use for: ${dot(a.use)}` : "", a.avoid ? ` Avoid: ${dot(a.avoid)}` : "", a.example && Object.keys(a.example).length ? ` Example params: ${JSON.stringify(a.example)}.` : ""].join("");
}
export function presetLine(d: PresetDescriptor): string {
  const params = d.params.length ? ` Params: ${d.params.map(paramText).join("; ")}.` : "";
  return `- ${d.id}: ${d.description}${d.kind === "textStyle" ? styleLook(d) : ""}${params}${aiHints(d)}`;
}

const FORMAT_SECTION = () => `{
  "format": "${STORYBOARD_FORMAT}",
  "schemaVersion": "${SCHEMA_VERSION}",   // always "${SCHEMA_VERSION}": the clip-centric schema (RULE 51)
  "meta": {
    "title": string, "logline"?: string, "synopsis"?: string, "style"?: string, "language"?: string,
    "aspect": "16:9" | "9:16" | "1:1" | "4:5" | "21:9",
    "textStyles"?: { "<style id>": TextStyle }   // one-off text looks for this storyboard; ids must not clash with preset ids
    "audioOutput"?: { "mode": "stereo" | "binaural", "environment"?: "room" | "outdoor" }   // spatial audio: stereo (default, speakers) or binaural (headphones); space sets the reverb (default room)
  },
  "assets": [ {
      "id": string,              // short unique id: letters, digits, "_", "-", "."
      "name": string,
      "type": ${STORY_ASSET_TYPES.map((t) => `"${t}"`).join(" | ")},
      "aspect"?: string,         // defaults to meta.aspect; reference sheets usually "16:9"
      "prompt": string,          // full, self-contained image/video generation prompt (required when source is "generate");
                                 // character and prop assets: a multi-angle reference sheet (turnaround);
                                 // for "html": a design brief for the AI that writes the clip as one .html file (see RULES);
                                 // an html asset's "references" are listed in its prompt for the code AI (images, other html clips)
      "references"?: (string | { "asset": "<asset id>", "role"?: "start-frame" | "identity" | "look" | "detail", "note"?: string })[],
                                 // other assets to attach when generating this one, IN THIS ORDER (Image 1, Image 2 …); a plain id
                                 // = role from its type; for an image "start-frame" means the base image to edit (no end-frame)
      "source": "generate" | "upload" | "json" | { "type": "lastFrame", "shot": "<shot id>" },
                                 // plain strings "generate" / "upload" / "json" (default "generate"); an object only for lastFrame; "html" and "audio" can't use lastFrame; "json" is audio only (a dionysus.audioclip/1 clip)
      "qa": string[],            // 2-5 concrete yes/no checks to verify the asset by looking
      "params"?: { "<key>": Param },  // "html" only: values the clip exposes, set per use by shots and layers (see RULES)
      "genDurationSec"?: number, // video assets only: the length to generate (0.5-120) when its shots or layers use less; they pick their part with "inSec"
                                 // a CLIP = a video asset named by a shot's "clip" (RULE 51); it carries everything that makes the clip:
                                 // its "prompt" (the full clip generation prompt), "qa" (2-5 checks for the clip), "camera"?: string, and
                                 // "references"?: [ { "asset": "<asset id>" | "<shot id>.keyframe", "role", "note"? } ] or a frame of an EARLIER shot's clip (RULE 50):
                                 // { "frameOf": "<earlier shot id>", "atSec"?: number, "role": "start" | "reference", "frameDesc": string };
                                 // ids may be "<asset id>@<state id>" = that asset's state, "<shot id>.keyframe" or "<shot id>.lastframe" (RULES);
                                 // the images attach IN THIS ORDER (Image 1, Image 2 …); at most one "start-frame" and one "end-frame"
                                 // "keyframe"?: { "prompt": string, "references"?: [ "<asset id>" | { "asset", "role"?, "note"? } ], "qa"?: string[] }
                                 // = the opening still to generate FIRST; the clip animates from it. The clip's images are then
                                 // Image 1 = the keyframe (start frame), Image 2 … = the clip's "references" (RULE 18)
      "states"?: [ { "id": string, "name"?: string, "prompt": string, "references"?: [ … as above ], "source"?: "generate" | "upload", "qa"?: string[] } ]
                                 // image-like assets only: the same thing in another state (lit, wet, at night …); use it as "<asset id>@<state id>" (RULES)
      "seriesRef"?: string,      // the id of an asset in the project's Series: write only { "id", "seriesRef" }; the definition, states
                                 // and uploads come from the Series (RULES)
      "series"?: true            // add this new asset to the project's Series so later episodes can reuse it
  } ],
  "shots": [ {                   // in playback order. Schema 3.1 (RULE 51): a shot has NO prompt; it plays a clip (a video asset)
      "id": string,
      "title": string,
      "description"?: string,
      "durationSec": number,     // 0.5–120; how long the shot stays on screen in the final edit, set by the story's pacing (NOT by the video model's limits)
      "clip": "<asset id>",      // render "ai" (default): the id of its clip, a "video" asset that carries the generation prompt, references, genDurationSec,
                                 // keyframe, camera and the clip's qa; one clip per shot, or the SAME clip in several shots to reuse one generation;
                                 // render "html": an html asset; render "still": an image asset (unless "background" is given)
      "inSec"?: number,          // seconds into a clip that several shots share: where this shot starts playing it (default 0)
      "dialogue"?: string | [ string | { "speaker"?: string, "text": string, "offscreen"?: boolean } ],
                                 // spoken lines; a list marks who says each; "offscreen": true = heard, not seen (no lip-sync; not a voiceover)
      "qa"?: string[],           // checks of the edit itself (text, layers, timing); the clip's own checks go on the clip asset
      "render"?: ${SHOT_RENDERS.map((r) => `"${r}"`).join(" | ")},   // default "ai" (generated clip); "html" = uploaded HTML animation; "still" = an image held on screen
      "background"?: "#rrggbb" | { "type": "linear" | "radial", "angle"?: number, "stops": [ { "color": "#rrggbb", "at"?: number } ] },
                                 // render "still" only, instead of "clip": a solid colour or a gradient the app draws (2-8 stops, "at" 0-1;
                                 // linear "angle" in degrees, 0 = bottom to top, 90 = left to right, default 180 = top to bottom); put titles in "layers"
      "params"?: { "<key>": value },   // render "html" only: this shot's values for the clip asset's "params"
      "captions"?: boolean,      // true = show "dialogue" (the lines' text) as subtitles over the shot
      "layers"?: Layer[],        // drawn in list order (later = on top)
      "effects"?: [ { "preset": "<video effect id>", "params"?: { ... }, "startSec"?: number, "endSec"?: number, "applyTo"?: "main" | "overlay" | "all" } ]   // default: whole shot, applyTo "main"
  } ],
  "connections"?: [ {
      "from": "<shot id>", "to": "<shot id>",     // adjacent shots only
      "kind": ${CONNECTION_KINDS.map((k) => `"${k}"`).join(" | ")},
      "note"?: string,
      "transition"?: { "preset": "<transition id>", "params"?: { "durationSec"?: number } }   // omitted = cut; default ${DEFAULT_TRANSITION_SEC} s
  } ],
  "audio"?: [ {                  // voiceover, music, ambience beds, sound effects, stings and recorded lines, placed by shot (assets of type "audio")
      "id"?: string, "asset": "<audio asset id>", "kind": "voiceover" | "music" | "sfx" | "ambience" | "sting" | "dialogue",
      "from": "<shot id>",       // the shot it starts in
      "atSec"?: number,          // seconds into "from" (default 0)
      "to"?: "<shot id>",        // plays to the end of this shot (same as or after "from"); omitted = the audio's own length; not for sting / dialogue
      "durationSec"?: number,    // stop after this many seconds (with "to": whichever comes first)
      "loop"?: boolean,          // music and ambience only: repeat to fill the span; default true for ambience, false for music; others never loop
      "line"?: number,           // dialogue only: the 1-based line of the "from" shot's "dialogue" list this recording is (an off-screen line)
      "volume"?: number,         // 0-1; default music 0.35, ambience 0.5, sting 0.8, others 1
      "fadeInSec"?: number, "fadeOutSec"?: number,  // default music and ambience 1 s each, others 0
      "volumeKeys"?: [ { "t": number, "v": number } ],   // volume curve: t = seconds from the cue start, v = 0 (silent) to 2, 1 = "volume"; linear between points
      "fx"?: { "preset": "<audio effect id>", "amount"?: number }   // sound effect (echo, telephone, radio…), amount 0-1 (default 1)
      "position"?: { "azimuth": number, "distance": number, "width"?: number },  // where the sound sits: azimuth degrees 0 front, -90 left, 90 right, ±180 behind; distance 0 (at the ear) to 1 (about 20 m); width 0-1, default 1 = keep a stereo file's own left/right image
      "pan"?: number,            // shorthand -1 (left) to 1 (right) = azimuth pan × 90, distance 0; "position" wins if both are given
      "positionKeys"?: [ { "t": number, "azimuth": number, "distance": number } ]   // moving sound: t = seconds from the cue start; linear, the shorter way round
  } ]
}

Layer (times in seconds from the shot start, 0 <= startSec < endSec <= durationSec; coordinates are 0-1 fractions of the frame from the top-left):
  Text:  { "id": string, "type": "text", "text": string, "startSec": number, "endSec": number,
           "position": { "x", "y" }            // text centre (preferred), OR
           "box": { "x", "y", "width", "height" },   // top-left + size; give exactly one of position / box
           "textStyle"?: "<text style id or meta.textStyles key>",
           "style"?: TextStyle,                // overrides the text style
           "anim"?: { "in"?: "<id>", "out"?: "<id>", "loop"?: "<id>", "durationSec"?: number },
           "blend"?: "<blend id>", "opacity"?: number (0-1, default 1),
           "follow"?: "frame" | "shot" }      // default "frame" (fixed); "shot" = moves with the shot's zoom/pan effects
  Media: { "id": string, "type": "html" | "image" | "video", "asset": "<asset id>", "startSec": number, "endSec": number,
           "box": { "x", "y", "width", "height" }, "blend"?: "<blend id>", "opacity"?: number (0-1), "follow"?: "frame" | "shot",
           "params"?: { "<key>": value },    // "html" layers only: this layer's values for the asset's "params"
           "inSec"?: number,                   // video only: seconds into the asset's clip where the layer starts (default: the upload's trim, else 0)
           "chromaKey"?: { "color": "#rrggbb", "range"?: number, "spill"?: number } }  // green screen: removes "color" (range 0-1 tolerance, default 0.4; spill 0-1 edge clean-up, default 0.5)
Param (an html asset's exposed value; "default" is required and must be valid):
  { "type": "text", "default": string } | { "type": "number", "default": number, "min"?: number, "max"?: number, "step"?: number }
  | { "type": "color", "default": "#rrggbb" } | { "type": "boolean", "default": boolean } | { "type": "select", "options": string[], "default": string }
  each may add "label"?: string (shown in the editor) and "description"?: string
TextStyle: { "font"?: "<font id>", "size"?: number (fraction of frame height, 0-1), "color"?: "#rrggbb", "align"?: "left" | "center" | "right", "bold"?: boolean,
             "italic"?: boolean, "letterSpacing"?: number (em, -0.2-1), "lineHeight"?: number (0.8-3),
             "strokeWidth"?: number (outline, fraction of font size, 0-0.3), "strokeColor"?: "#rrggbb",
             "shadow"?: { "color", "blur", "x", "y" } | null (fractions of font size), "background"?: { "color", "opacity" } | null,
             "effect"?: "<text effect id>" | "none", "effectColor"?: "#rrggbb" }
Text is one line per "\\n" and is never wrapped: keep lines short. Without "size", text uses the style's size (else 0.1), or fits the box height.`;

/** Categories of `kind` in registry order (first appearance), each with its presets. */
export function presetsByCategory(kind: PresetKind): { category: string; presets: PresetDescriptor[] }[] {
  const groups = new Map<string, PresetDescriptor[]>();
  for (const d of listPresets(kind)) {
    const c = d.category?.trim() || "Other";
    groups.set(c, [...(groups.get(c) ?? []), d]);
  }
  return [...groups].map(([category, presets]) => ({ category, presets }));
}

/** The preset catalogue (V2-SB-GUIDE-GENERIC): generated from the descriptors, grouped by kind, then by category. */
export function presetsSection(): string {
  const blocks = GUIDE_KINDS.map(({ kind, title, usedIn }) => {
    const groups = presetsByCategory(kind).map(({ category, presets }) => `[${category}]\n${presets.map(presetLine).join("\n")}`);
    return `${title} — ${usedIn}:\n${groups.join("\n")}`;
  });
  blocks.push(`Fonts — TextStyle "font":\n${FONTS.map((f) => `- ${f.id}: ${f.description}`).join("\n")}`);
  return `Only these ids may be used. Omitted params take their defaults. Within each kind, presets are grouped by [category].\n\n${blocks.join("\n\n")}`;
}

/** How a storyboard becomes a video, for planners that have never seen Dionysus. Story-neutral; names no preset ids. */
export const HOW_IT_WORKS = `Every prompt stands alone. Each asset and each clip may be generated by a different AI agent, chat or tool that has never seen this storyboard, the story or the other prompts: it gets only that one prompt and its attached images. So every prompt repeats the identity, look and style it needs (RULE 31), and the app adds the references and a consistency block (the style bible plus the character and prop sheets attached) when it copies a clip prompt.

A storyboard is one JSON object with three lists:
- "assets": everything that must exist before the clips can be made: characters, locations, props, a style frame, uploads, and "frame" assets taken from the last frame of a shot for continuity. Each asset has its own self-contained generation prompt, the other assets it is made from ("references") and QA checks.
- "shots": the clips of the final edit in playback order. Each plays a clip (a "video" asset with the clip generation prompt and the images attached to the generator; several shots may share one clip), its on-screen length ("durationSec") and, optionally, text layers and video effects that the editor draws on top.
- "connections": what happens between two adjacent shots: a plain cut, continuity from the previous shot's last frame, or a transition preset.
The user imports the JSON into Dionysus, which checks it and lists every problem with its path. The app then walks the user through generating (with their own AI tools and your prompts) or uploading each asset and clip, in dependency order. Finally the editor assembles the timeline: shots in order, trimmed to "durationSec", with your text layers, effects and transitions applied.
So split the work: generation prompts describe only the picture and its motion; on-screen text, post camera moves, looks and transitions are done by the editor with presets and stay out of the prompts.`;

/** Generic guidance for picking presets; the per-preset "Use for" / "Avoid" hints in the catalogue come from the descriptors. */
export const CHOOSING_PRESETS = `Presets are the editor's built-in tools: video effects on a shot, transitions on connections, text styles and text animations on text layers. Each one in the PRESETS section has an id, a one-line description, its params (range, default and unit) and sometimes "Use for" / "Avoid" hints.
- Choose by purpose: match the description and hints to what the moment needs (mood, energy, what the viewer should notice), not the name alone.
- Less is more: most cuts need no transition (omit it). Use one or two transition styles for the whole video and save the energetic ones for beats that call for them. Use at most one or two effects per shot.
- Effects are post-production: use them for camera moves the clip doesn't have, colour or light looks, and fades. When an effect adds the camera move, the generation prompt says "static camera".
- Stay consistent: give recurring text one look (a text style preset or a "meta.textStyles" entry) and the same in/out animation throughout; keep loops for short emphasis.
- Params: omit them to use the defaults and set only what you need, within the listed range and unit. Unknown ids, unknown params and out-of-range values are reported on import.`;

/**
 * Planner rules (V2-SB-GUIDE-GENERIC). Their numbers are public: STORYBOARD_FORMAT.md, users and other AIs cite them
 * ("RULE 13"), so the list is append-only: add new rules at the end, never reorder or delete; to retire a rule,
 * rewrite its text. aiGuide.test.ts pins the key order. Rules stay story-neutral (no names from an example story).
 */
export const RULE_LIST: readonly { key: string; text: string }[] = [
  { key: "reusable-assets", text: "Every recurring character, location, prop and the overall style gets ONE reusable asset with a detailed prompt; shots reference these ids instead of repeating descriptions. When one of them changes during the story (a lamp lit, a coat soaked, a street at night), give that asset \"states\" (RULE 29) instead of a separate asset." },
  { key: "standalone-prompts", text: "Write prompts that work on their own (a generator only sees that prompt plus the reference images). Repeat key visual details (clothes, colours, lighting, style) in every prompt." },
  { key: "last-frame-continuity", text: `When a shot must continue seamlessly from the previous one, use "<previous shot id>.lastframe" (RULE 35) in the next shot's "assets" or as its "start-frame" reference (or declare a "frame" asset with "source": { "type": "lastFrame", "shot": "<previous shot id>" } when it needs its own name or checks), and mark the connection "continuity". Never make a shot depend on its own last frame or create loops.` },
  { key: "uploads", text: `Use "source": "upload" for things the user already has (logos, real photos, products).` },
  { key: "qa-checks", text: "Every asset and shot gets 2–5 QA checks that a person can verify by looking: identity consistency, key props, framing, artefacts (extra fingers, warped text, watermarks)." },
  { key: "ids", text: `Keep ids short and stable (e.g. "hero", "kitchen", "s1", "s1-end"). Shots are listed in order; "connections" may be omitted for simple hard cuts.` },
  { key: "valid-json", text: "Output valid JSON only: double quotes, no comments, no trailing commas." },
  { key: "text-in-layers", text: "Every piece of on-screen text (titles, cards, labels, captions) goes into a text layer (or the params of a reusable html text card, RULE 24), never into a generation prompt. Prompts ask for clean, empty surfaces where the text will sit." },
  { key: "html-only-for-graphics", text: `Use "html" assets and "render": "html" only for animated, 3D or three.js graphics. Plain text over a shot is a text layer; a designed title or text-only card is one reusable "html" asset with params (RULE 24).` },
  { key: "transitions-and-effects", text: `Transitions go on connections. Post camera moves (push-in etc.) and looks go in the shot's "effects", and the generation prompt then says "static camera".` },
  { key: "known-presets", text: "Only use preset ids listed in the PRESETS section." },
  { key: "param-units", text: `Preset params use the units noted in brackets in the PRESETS section; "fade-in"/"fade-out" "length" is a fraction (0.05–1) of the effect's time range, not seconds.` },
  { key: "duration", text: `"durationSec" is how long the shot stays on screen in the final edit (its planned edit length). Decide it from the story's pacing, NOT from what the video model can generate, and never put the planned length only in "description" or notes. If the video model can't render that length (it has a minimum or fixed lengths, e.g. 6, 10 or 15 s), keep "durationSec" at the planned length and set "genDurationSec" to the length to ask the model for; it must be greater than "durationSec" (omit it when they are equal). When the clip is uploaded the app trims it to "durationSec" and the user picks which part to keep. Example: a 4 s beat with a model that renders 6 s minimum: "durationSec": 4, "genDurationSec": 6. Montage (a quick run of glimpses, e.g. three 2 s moments of a journey) needs no special field: write it as consecutive short shots (about 1-3 s each, e.g. three shots with "durationSec": 2), each with its own prompt, assets and QA checks, joined by plain cuts (omit their connections, or keep any transition very short, RULE 15). Use "genDurationSec" when the model can't render that short, keep the style and references the same across the run, and tie it together with one audio cue (a music bed or voiceover "from" the first montage shot "to" the last) rather than a longer shot.` },
  { key: "references-block", text: `Every clip prompt starts with a "References:" block that numbers the images attached to the clip in the order of the shot's "references" (else its "assets"): "Image 1 (<asset name>): …", one line each, saying explicitly whether the image is the START FRAME (or END FRAME) or only a reference, and what to take from it (identity, overall look, or materials and colours only, not its framing or wide view). Then state the framing from the first frame to the last. Set "references" with roles whenever the order or use is not obvious from the asset types.` },
  { key: "transition-overlap", text: `A transition in "connections" overlaps the two shots, centred on the cut: it adds no time and eats half its length from the end of the "from" shot and half from the start of the "to" shot. It is clamped to half the shorter of the two shots. For example, a 0.8 s transition out of a 2.5 s shot blends the last 0.4 s of that shot with the first 0.4 s of the next, and the total length stays the same; keep transitions short on short shots so their key action isn't covered.` },
  { key: "identity-portrait", text: `Character assets are multi-angle reference sheets (RULE 32). When a sheet is an "identity" reference, its line in the "References:" block says it is a reference sheet: keep the identity (face, body, clothes), never reproduce its layout (several views, panels, labels). For a shot that needs one exact pose, a keyframe (RULE 18) made from the sheet works better than the sheet alone.` },
  { key: "asset-references", text: `An asset made from other assets lists them in its "references" in attach order, as objects with a "role" when the use is not obvious from the type. Its prompt then starts with the same numbered "References:" block as a clip prompt; for an image, "start-frame" means the base image to edit (there is no end frame). Example: a close-up of the hero holding a mug: "references": [{ "asset": "mug", "role": "detail", "note": "glaze and colour only" }, "hero"], prompt "References:\\nImage 1 (Blue mug): reference only: materials, colours and objects only; glaze and colour only.\\nImage 2 (Hero): reference only: keep this identity (face, body, clothes).\\n\\nClose-up of …".` },
  { key: "keyframe", text: `Keyframe then animate: when the opening composition matters (a character's pose, a precise layout, a hero product shot), give the "ai" shot a "keyframe": { "prompt", "references", "qa" }. The app turns it into an image asset "<shot id>.keyframe" named "Keyframe · <shot title>" that is made first. Numbering of the clip's images when a shot has a keyframe: Image 1 is always the keyframe, the START FRAME; Image 2, 3 … are the shot's "references" in their order, then the shot's other "assets" in "assets" order (the numbering without a keyframe, shifted by one). Do not also give the shot a "start-frame": one in "references", or an inferred one (a "frame" or last-frame asset), is attached as details only. The keyframe's own "references" are numbered separately, from Image 1, in the keyframe prompt; they are attached to the clip only if they are also in the shot's "assets" or "references". Other shots and assets may reference this keyframe as "<shot id>.keyframe" (RULE 26). The keyframe prompt describes one still image (with its own "References:" block, as for an asset); the clip prompt starts with a "References:" block in the clip numbering above and then describes only the motion from that frame. Example: "keyframe": { "prompt": "References:\\nImage 1 (Hero): reference only: keep this identity (face, body, clothes).\\nImage 2 (Café): reference only: materials, colours and objects only.\\n\\nThe hero sits at a café table, both hands around a blue mug …", "references": ["hero", "cafe"], "qa": ["The hero's face matches the reference"] } with the shot's "assets": ["hero", "cafe"], clip prompt "References:\\nImage 1 (Keyframe · Morning coffee): START FRAME: the clip opens on exactly this image.\\nImage 2 (Hero): reference only, not a frame: keep this identity.\\nImage 3 (Café): reference only, not a frame: materials and colours only.\\n\\nShe slowly lifts the mug …".` },
  { key: "audio", text: `Audio: put each voiceover, music bed or sound effect in "audio" as a cue on an asset of type "audio" (source "generate" with a prompt for the user's voice/music/sound tool, e.g. the exact voiceover script and voice, or "upload"). "from" is the shot it starts in, "atSec" the offset into that shot, "to" the last shot it plays under. A music bed usually runs "from" the first shot "to" the last with "volume" 0.2-0.4 under speech; a voiceover spans the shots it describes; a sound effect sits at the moment in one shot ("atSec") with no "to". Example: { "asset": "score", "kind": "music", "from": "s1", "to": "s6", "volume": 0.3, "fadeOutSec": 2 }, { "asset": "door-slam", "kind": "sfx", "from": "s4", "atSec": 1.2 }. Background sound under several shots is kind "ambience" and a short musical hit at one moment is a "sting" (RULE 27). Do not put spoken lines that the video model renders (shot "dialogue") into a voiceover too; a voice heard in the scene but not seen is an off-screen dialogue line, not a voiceover (RULE 28).` },
  { key: "layer-follow", text: `Layers stay fixed to the frame by default: a shot's video effects (e.g. "ken-burns" zoom and pan) move only the picture, so titles, labels and logos stay put and readable. Give a layer "follow": "shot" only when it belongs to the scene and must move with the picture, e.g. a name tag pinned to a sign or a label on an object while the shot slowly zooms: { "id": "tag", "type": "text", "text": "ROOM 12", "startSec": 0, "endSec": 4, "position": { "x": 0.62, "y": 0.4 }, "follow": "shot" }. It only has an effect when an effect moves or zooms the shot while the layer is on screen.` },
  { key: "text-style-extras", text: `Keep text readable on any picture: give light text an outline ("strokeWidth" about 0.04-0.08 with a dark "strokeColor"), a soft "shadow", or a "background" box (captions, lower thirds). Use "letterSpacing" (in em) for airy titles, "lineHeight" for multi-line cards, "italic" for emphasis, and a text "effect" with "effectColor" only for stylised titles. Sizes and offsets are fractions of the font size; null removes a style's shadow or background. Example: "style": { "color": "#ffffff", "strokeWidth": 0.06, "strokeColor": "#000000", "shadow": { "color": "#000000", "blur": 0.3, "x": 0, "y": 0.04 } }. Put a look used on several layers into "meta.textStyles" once.` },
  { key: "blend-overlays", text: `For overlays (light leaks, flares, dust, film grain, paper or ink textures) use an image or video layer with a "blend" mode and, if needed, an "opacity" below 1: "screen" or "add" for elements on black (the black disappears), "multiply" for elements on white (the white disappears), "overlay" or "soft-light" for textures on mid grey. Example: { "id": "leak", "type": "video", "asset": "light-leak", "startSec": 0, "endSec": 3, "box": { "x": 0, "y": 0, "width": 1, "height": 1 }, "blend": "screen", "opacity": 0.7 }. Ask for the overlay asset full-frame on a plain black, white or grey background. Leave "blend" out ("normal") for titles, logos and pictures that should simply cover the shot.` },
  { key: "html-clip-package", text: `An "html" asset's "prompt" is a design brief for the AI that will write the clip, not code: what it shows, how it moves over its length, colours, type and layout. List the media it uses (logos, photos, footage, music) in its "references"; the app copies the brief together with the HTML clip package instructions (format "dionysus.htmlclip/1", spec HTML_CLIP_PACKAGE.md next to this guide), filled in with the asset's size, length, bound assets and allowed libraries, and the user pastes the AI's single .html file back as a version.` },
  { key: "html-params", text: `Reuse one "html" asset with "params" instead of duplicating it: when shots or layers show the same design with different words, numbers or colours (title cards, text-only cards, chapter and end cards, lower thirds, counters), make ONE html asset, declare what varies in its "params" ({ "<key>": { "type": "text" | "number" | "color" | "boolean" | "select", "default": …, "label"?, "description"? } }, numbers may add "min", "max", "step", a select lists its "options"), and give each use its own values: a text-only shot is { "render": "html", "clip": "<asset id>", "params": { "text": "THE END" } }, a layer over a shot is { "type": "html", "asset": "<asset id>", "box": { "x": 0, "y": 0, "width": 1, "height": 1 }, "params": { "text": "5:58 AM" } }. Omitted keys use the default; a value must match its type (numbers within min–max, a select one of its "options", colours "#rrggbb"). The brief describes the design for any value (long and short text) and names the params; the app tells the clip's AI to expose exactly these params and read them at render time. Keep plain captions over a shot as text layers.` },
  { key: "video-asset-trim", text: `A "video" asset shown as a layer (a light leak, dust, smoke, a screen insert) is often generated longer than the layer needs, because video models have minimum or fixed lengths. Give the asset "genDurationSec" (the length to generate, 0.5-120, video assets only) and give each video layer "inSec": the second of the clip the layer starts from (default: the part the user picks when uploading, else 0). The layer still lasts endSec - startSec; keep inSec + that length within genDurationSec. One generated clip can feed several layers with different "inSec" values. Example, a 2 s screen-blend overlay cut from a 6 s clip: asset { "id": "dust-leak", "type": "video", "genDurationSec": 6, ... } and layer { "id": "s3-dust", "type": "video", "asset": "dust-leak", "startSec": 0, "endSec": 2, "inSec": 3, "box": { "x": 0, "y": 0, "width": 1, "height": 1 }, "blend": "screen" }. For a shot's own clip use the shot's "genDurationSec" instead (RULE 13).` },
  { key: "keyframe-refs", text: `A shot's keyframe (RULE 18) can be reused: another shot, another keyframe or an asset may list "<shot id>.keyframe" in its "assets" or "references" like an asset id, with any role: "start-frame" to open on exactly that composition (returning to the same set-up), "identity" for a pose or character, "look" for the same light and palette, "detail" for materials and colours only. A plain id is treated like a "frame" asset (a start frame, or details only when the shot already has a start frame or its own keyframe). That shot must have a "keyframe", a shot can't list its own, and there must be no loops (a keyframe made from something that needs it first). The app makes the referenced keyframe first and attaches the version picked for it, named "Keyframe · <shot title>" in the References block. Example: shot s3 { "assets": ["hill", "s1.keyframe"], "references": [{ "asset": "hill", "role": "detail" }, { "asset": "s1.keyframe", "role": "look", "note": "same pre-dawn palette and mist" }] }, clip prompt "References:\nImage 1 (Hill road): reference only, not a frame: materials, colours and objects only.\nImage 2 (Keyframe · The climb): reference only, not a frame: overall look; same pre-dawn palette and mist.\n\n…".` },
  { key: "audio-ambience-sting", text: `Background sound that lasts (wind, rain, traffic, room tone, a crowd) is kind "ambience": a bed "from" the first shot it is heard in "to" the last, looped to fill that span ("loop": false plays it once), default volume 0.5 with 1 s fades in and out. Ask for a loopable 20-60 s recording. A short musical hit or whoosh on a moment (a title appearing, a reveal, a cut to black) is kind "sting" at "atSec" in one shot, with no "to". A "sfx" is a one-off sound at one moment too: never give a sound effect a "to" to make it last, it is not looped and stops when the sound ends; use "ambience" instead. Music repeats only with "loop": true. Example: { "asset": "dawn-wind", "kind": "ambience", "from": "s1", "to": "s3" }, { "asset": "title-chime", "kind": "sting", "from": "s3", "atSec": 1 }.` },
  { key: "offscreen-dialogue", text: `Write a shot's "dialogue" as a list of lines when who speaks matters: { "speaker": "ANNA", "text": "Who's there?" } is said on screen (the video model lip-syncs it); add "offscreen": true for a voice that belongs to the scene but whose speaker is not in frame (behind a door, on the phone, calling from out of shot): nobody in frame moves their lips. It is not a voiceover (narration over the film, an "audio" cue of kind "voiceover"). The app appends a numbered "Dialogue:" block to the clip prompt marking each line on screen (lip-synced) or OFF-SCREEN (heard, not seen); write the clip prompt so the speaker is out of frame and say how the people in frame react. If an off-screen line is recorded separately instead of generated with the clip, also add an "audio" cue of kind "dialogue" "from" that shot with "line" (its 1-based number in the list) and "atSec"; the Dialogue block then tells the model not to voice it. "captions": true shows the lines' words. Example: "dialogue": [{ "speaker": "FRIEND", "text": "You made it!", "offscreen": true }].` },
  { key: "asset-states", text: `When a character, location, prop, style, image or frame appears in more than one state (a lamp off and on, a coat dry and soaked, a street by day and at night, a vase whole and broken), keep ONE asset and add its other looks to its "states": [ { "id", "name"?, "prompt", "references"?, "source"?, "qa"? } ]. Refer to a state as "<asset id>@<state id>" anywhere an asset id goes: a shot's "assets" and "references", a keyframe's or another asset's "references", a still shot's "clip", an image layer's "asset". Each state gets its own prompt, checks and versions; its type and aspect are the asset's (not allowed on video, audio or html assets). The app makes the base asset first and attaches it to the state as Image 1 so it stays the same thing (role "identity" for a character, else from its type); list the base yourself in the state's "references" to choose its role, e.g. "start-frame" to edit the base image. State ids use letters, digits, "_" and "-" only; a state can't use another state of the same asset. Write the state prompt with its own "References:" block and describe only what changes. Use the base id for the default look and "<asset id>@<state id>" only where the state shows; don't list both in one shot unless both appear. Example: asset "hill" with "states": [{ "id": "sunrise", "name": "Sunrise", "prompt": "References:\nImage 1 (Hill road): the base image to edit: keep the road, hill and valley exactly; change only the light.\n\nThe same winding hill road as the sun rises …", "references": [{ "asset": "hill", "role": "start-frame", "note": "the same road and hill; only the light changes" }], "qa": ["Same road, hill and valley as the base image"] }], used by shot s3 as "assets": ["hill@sunrise", "s1.keyframe"]. In "References:" blocks a state is named "<asset name> · <state name>", e.g. "Image 1 (Hill road · Sunrise)".` },
  { key: "stable-ids-reimport", text: `When the user sends back a storyboard to revise (exported from the app, format "dionysus.storyboard/1"), return the WHOLE revised storyboard JSON and keep every id stable: an asset, state or shot that stays keeps its exact "id" even when its name, prompt or place in the order changes, new things get new ids, and an id is never reused for something different. The user re-imports it and the app matches it to the board by id: everything with an unchanged id keeps its uploads, picked versions, trims and checks, and anything whose id is missing is removed after the user confirms. Renaming an id therefore throws its work away; only change an id when the thing is really replaced.` },
  { key: "self-contained-prompts", text: `Every prompt is self-contained, because a different AI agent, chat or tool may make each asset and each clip and sees only that one prompt plus its attached images. In every clip and keyframe prompt repeat: who is in it and what they look like (face, hair, clothes), the key props, the location, and the style from "meta.style"; never write "as before", "the same as shot 2" or a name the generator can't see. Start with the "References:" block naming each attached image (RULE 13), then a "Consistency:" paragraph (the style bible in one line, then one line per character or prop sheet attached: what must stay the same), then the action. When you leave the Consistency paragraph out, the app adds one built from "meta.style" and the attached character, prop, location and style sheets when it copies the prompt.` },
  { key: "reference-sheets", text: `Write every "character" asset prompt as a multi-angle reference sheet (turnaround): the same person full body from the front, three-quarter, side and back, plus a face close-up; neutral pose, even light, plain background, no text or labels. Every important prop (one that recurs, is handled, or must look the same in several shots) gets its own "prop" asset written the same way: a reference sheet from several angles plus close-ups of its details. Reference sheets usually use "aspect": "16:9". Attach them to every shot and keyframe that shows that character or prop.` },
  { key: "html-code-refs", text: `An "html" asset can list other assets in "references" (images such as a logo, a style frame or a character sheet, or other html clips): the app attaches them to the asset's Copy prompt and names each one ("Code references" for html clips), so the AI writing the clip knows what to match or reuse. Html assets can in turn be references of shots and other assets. Keep html briefs focused on the motion and logic: the app asks the code AI to write the work in JavaScript through dionysus.clip (init / render per frame) with a minimal HTML shell (one <canvas>), and full HTML or CSS only when the design truly needs it.` },
  { key: "shot-background", text: `A still shot that is only a colour or gradient with text or graphics on top (a title card, credits, a chapter card) needs no image: give it "render": "still" and "background" instead of "clip": a hex colour like "#000000", or { "type": "linear", "angle": 180, "stops": [ { "color": "#000000" }, { "color": "#1a2a4a" } ] } ("radial" goes from the centre out; 2-8 stops; "at" 0-1 places a stop). Put the words in text layers and graphics in image, video or html layers ("layers", drawn in order on top of the background). Use "clip" or "background", not both. Example: { "id": "s9", "title": "Title", "durationSec": 3, "prompt": "", "assets": [], "render": "still", "background": "#000000", "layers": [ { "id": "t", "type": "text", "text": "PART ONE", "startSec": 0, "endSec": 3, "position": { "x": 0.5, "y": 0.5 } } ], "qa": ["Reads PART ONE"] }.` },
  { key: "lastframe-refs", text: `"<shot id>.lastframe" is the last frame of that shot's clip and can be used anywhere an asset id goes (a shot's "assets" and "references", a keyframe's or an asset's "references") without declaring an asset: the app adds a "frame" asset named "Last frame · <shot title>", takes the frame from the clip version picked for that shot as soon as it is uploaded (and again when a different version is picked or it is trimmed), and attaches it in "references" order. Use it with role "start-frame" for seamless continuity (RULE 3) or "look" / "detail" to match a moment. The shot must be an "ai" shot listed before the one using it, a shot can't use its own last frame, and there must be no loops.` },
  { key: "chroma-key", text: `To put a person, animal or object over a shot without its background, ask for the asset (image or video) shot in front of a flat, evenly lit pure green (#00ff00) screen — blue (#0000ff) when the subject is green — with no shadows on the screen and no green on the subject, then give its layer "chromaKey": { "color": "#00ff00", "range": 0.4, "spill": 0.5 }. "range" (0-1) is how far from the colour is removed (raise it to about 0.5-0.6 if a green fringe is left; lower it if the subject gets holes), "spill" (0-1) takes the green tint off edges and hair. html layers may be keyed too. Example: { "id": "birds", "type": "video", "asset": "birds-green", "startSec": 0, "endSec": 3, "box": { "x": 0, "y": 0, "width": 1, "height": 0.6 }, "chromaKey": { "color": "#00ff00", "range": 0.4, "spill": 0.6 } }. Use "blend" instead for elements on black or white (RULE 22).` },
  { key: "audio-shaping", text: `Shape audio cues instead of asking for new recordings: "volumeKeys" is a volume curve over the cue (points { "t": seconds from the cue start, "v": 0-2, 1 = the cue's "volume" }, linear in between, the first and last values hold) — use it to duck music or ambience under a voiceover or title and swell it after, e.g. "volumeKeys": [ { "t": 4, "v": 1 }, { "t": 4.5, "v": 0.3 }, { "t": 9, "v": 0.3 }, { "t": 10, "v": 1 } ]. "fx" adds a sound effect from the audio effects list with an "amount" 0-1: "telephone" for the far side of a phone call, "radio" for broadcasts and walkie-talkies, "pa-announcement" for station or stadium loudspeakers, "hall" or "room" to place a dry voice in a space, "underwater" for muffled sound (underwater, behind a wall), "robot" for machine voices. Example: { "asset": "caller", "kind": "dialogue", "from": "s2", "line": 1, "fx": { "preset": "telephone", "amount": 1 } }. Keep fades ("fadeInSec", "fadeOutSec") for simple starts and ends.` },
  { key: "audio-json", text: `Simple music and sound effects (a chime, a notification, a whoosh, a riser into an impact, a short beat, an ambient pad, wind or rain) can be "source": "json" on an "audio" asset instead of "generate": the user's AI writes a "dionysus.audioclip/1" JSON (spec AUDIO_CLIP_FORMAT.md next to this guide: tempo, tracks of synth notes, drums, noise or generated sfx, with volume, pan, reverb, delay, filter and params) and Dionysus renders it, so it is exact, repeatable and editable in the Audio editor. Its "prompt" is a sound brief (what it sounds like, mood, key or tempo, length). Use "generate" for voices, real recordings and full songs; "json" is for audio assets only.` },
  { key: "long-story-parts", text: `For a long video (more than about 15 shots, or whenever one reply would get very long), work in parts instead of one huge JSON. First agree an outline with the user in plain text: the numbered shot list (id, title, length, one-line beat) and the asset list with ids. Then reply with part 1: a complete storyboard ("format", "meta", every asset you already know, and the first batch of about 8-12 shots). Then reply with one part per message, each a JSON object with "format", a "part" object and only what it adds or changes, and no "meta": { "format": "dionysus.storyboard/1", "part": { "index": 2, "of": 4, "after": "s10" }, "shots": [ …s11 to s20… ], "assets": [ …new or changed assets… ], "audio": [ …cues… ], "connections": [ … ] }. The user imports the parts in order (Storyboard → Import) and Dionysus merges each into the board by id: an asset, shot, cue or connection with an existing id (connections by "from"/"to") is replaced, a new one is added (new shots go after "part.after", else at the end), "part": { "remove": ["s7"] } deletes ids, and "meta" fields, when given, are merged. Each part is checked together with the board, so it may only use assets from an earlier part or itself; keep every id stable and don't repeat unchanged shots.` },
  { key: "web-mcp", text: `If you can call Dionysus tools (WebMCP: get_guide, get_storyboard, create_storyboard, add_shot, update_shot, …) because the user's browser connects you to the open app, edit the board with them instead of writing JSON: call get_storyboard first; create_storyboard when there is none (meta, the assets you know, and the first shot); add each asset before the shots that use it; then add the shots one at a time in story order; make changes with the update_ and set_ tools; call validate at the end and send_to_timeline only when the user asks. Every call is checked by these same rules: a rejected call changes nothing and says why, so fix the arguments and call again. The user sees each change live and can undo it.` },
  { key: "series-reuse", text: `Series: when the prompt lists SERIES ASSETS, this video is an episode of a series and those characters, props, locations and styles already exist. Reuse them, never redefine them: in "assets" write only { "id": "<series id>", "seriesRef": "<series id>" } (keep the same id so shots read naturally), then use the id, or "<id>@<state>" for a listed state, in shots, references, layers and other assets' references as usual. Dionysus fills in the name, type, prompt, states, QA and the user's chosen uploads from the Series, and adds Series assets they are made from. Extra fields next to "seriesRef" are ignored (the Series definition wins). A "seriesRef" that isn't in the list is an error, so copy ids exactly.` },
  { key: "series-promote", text: `Series: give a new asset "series": true when later episodes will need it too (a recurring character, the show's main locations, its style). Leave one-off things out (a prop used once, last frames, keyframes). Without a SERIES ASSETS list the project may not be in a series: then define every asset in full; "series": true is still allowed and is applied when the user adds the project to a series.` },
  { key: "series-tools", text: `Series with Dionysus tools (WebMCP): call list_series_assets before adding characters, props, locations or styles; use_series_asset adds one linked to the board; promote_to_series marks a board asset for the Series. Editing a linked asset's definition changes it in every episode, so only do that when the user asks; otherwise ask them to detach it first (Asset → Detach from series).` },
  { key: "effect-apply-to", text: `An effect's "applyTo" picks the picture it changes: "main" (the default) changes only the shot's own clip, under every layer, so titles and overlays stay fixed; "overlay" changes only the shot's image, video and html layers (e.g. shake a sticker or blur a screen insert, leaving the shot still); "all" changes the whole composited frame — the shot, its overlays and its text together — like moving the camera over the finished picture. Use "all" when an overlay frames or keys the shot, e.g. a TV-set overlay with a green-screen hole showing the shot: a push-in with "main" zooms only the picture inside the TV, with "all" the TV and the picture zoom together. Example: "effects": [ { "preset": "ken-burns", "params": { "zoom": 0.15 }, "applyTo": "all" } ]. Layers with "follow": "shot" (RULE 20) follow only "main" effects.` },
  { key: "typewriter-cursor", text: `Typewriter cursor: a text layer with "anim": { "in": "typewriter" } can take "inParams": { "cursor", "blink", "after", "scramble" }. "cursor" is the cursor characters: "" (default) = none; one character ("|" or "_") = a cursor right after the typed text; several ("0123456789", "01", "#$%&") = a decode/scramble effect where each new character flickers through random ones of them for "scramble" seconds (0–1, default 0.15) before it resolves. "blink" = cursor blinks per second after typing (0–6, default 2; 0 = solid). "after" = what the cursor does when typing ends: "blink" (default, keep blinking), "hide" or "fade" (fades out over 0.5 s). Typing lasts "anim.durationSec". The scramble is seeded by time, so preview and export match exactly. For a sci-fi location/date caption use the "sci-fi-caption" textStyle (bundled Share Tech Mono, right-aligned, digit scramble) at the bottom right, e.g. { "type": "text", "text": "SEATTLE / YEAR 2027", "position": { "x": 0.62, "y": 0.9 }, "textStyle": "sci-fi-caption", "anim": { "in": "typewriter", "durationSec": 1.5, "inParams": { "cursor": "0123456789", "after": "fade" } } }. Bundled sci-fi fonts (work offline, packed into project files): orbitron, share-tech-mono, audiowide, rajdhani, exo-2.` },
  { key: "link-to-main", text: `Link to main: on Send to Timeline every shot layer, caption, effect and audio cue that fits inside its shot is linked to that shot's main clip, so it moves when the shot is moved, reordered or rippled, is cut to fit when the shot is trimmed shorter, goes to the half holding its start when the shot is split, and is deleted with the shot. Write "link": false on a layer or an audio cue to keep it free (e.g. a music bed or a logo that must stay at a fixed time across shot edits); leave "link" out for the default (linked). Only false is meaningful. Example: "layers": [ { "id": "logo", "type": "image", "asset": "logo", "startSec": 0, "endSec": 5, "box": { "x": 0.8, "y": 0.05, "width": 0.15, "height": 0.15 }, "link": false } ]. Audio cues spanning several shots are never linked.` },
  { key: "fill-needs-prompt", text: `Fill needsPrompt: after the user edits the timeline and presses Sync to Storyboard, clips that came from no shot are added to the storyboard with "needsPrompt": true (shown as "⚠ Needs description / prompt"): a main-track clip becomes a new shot (id "shot-tl-N", empty "prompt"), a clip on another track becomes a layer ("tl-layer-N") or audio cue ("cue-tl-N") of the shot it is linked to. You MUST fill every needsPrompt item when you revise the JSON: give a shot a "description" and a full self-contained "prompt" (describe what the clip shows, keep its id, durationSec and order), give a layer or cue a "description". Filling it clears the flag on re-import; never delete those items and never set needsPrompt yourself. Shots, layers and cues with "removedFromTimeline": true had their clip deleted on the timeline: keep them unchanged unless the user asks to drop them. Example: { "id": "shot-tl-1", "title": "Timeline clip 1", "durationSec": 4, "needsPrompt": true, "description": "", "prompt": "" } becomes { "id": "shot-tl-1", "title": "Harbour at dusk", "durationSec": 4, "description": "Wide shot of Victoria Harbour as the lights come on", "prompt": "Wide static shot of a harbour at dusk, ferries crossing, skyline lights switching on, warm-to-blue sky, 24fps cinematic" }.` },
  { key: "review-timeline", text: `Review the cut: with WebMCP timeline tools, after editing the timeline (or after send_to_timeline) call get_timeline, then review_lint, and look at contact_sheet (and capture_frame at any time you doubt). Fix every error and warning it lists with move_clip, trim_clip, split_clip, delete_clip, set_clip_props and add_clip (gaps and black frames, very short clips, text off the frame, audio clipping, missing media, layers not linked to a main clip, needsPrompt items), then run review_lint again until only notes you chose to keep are left. Never guess clip ids or times: read them from get_timeline.` },
  { key: "spatial-audio", text: `Spatial audio: an audio cue (or, with set_clip_props, a clip with sound) can take "position": { "azimuth", "distance", "width"? } — azimuth in degrees, 0 = in front, -90 = left, 90 = right, ±180 = behind; distance 0 (at the ear) to 1 (far, about 20 m), which lowers the level, darkens the tone and adds reverb; "pan" -1..1 is a shorthand (azimuth = pan × 90). "positionKeys" [{ "t", "azimuth", "distance" }] moves the sound (t = seconds from the cue start). Stereo files already carry their own left/right movement: "width" (0-1, default 1) keeps that image while the pair is placed, so do not set width 0 unless you want it mono; mono files are point sources. Leave music centred unless asked. meta "audioOutput": { "mode": "binaural" } is for headphones (front/behind cues, HRTF); "stereo" (default) is for speakers and phones; "environment" "room" (default) or "outdoor" sets the reverb. Omit all of these to keep the sound unchanged.` },
  { key: "frame-of", text: `Frame of another shot: when a shot must start from, or match, a frame INSIDE an earlier shot's clip (not its last frame, RULE 35), e.g. shot 1 is a man at his computer noticing objects on the desk and the camera then pans to reveal a second person, and shot 2 should start from the middle of that move, add to the later shot's "references": { "frameOf": "<earlier shot id>", "atSec": <seconds into that clip>, "role": "start" | "reference", "frameDesc": "…" }. "start" makes the frame the START FRAME of the shot; "reference" attaches it as a reference image only. "frameDesc" is REQUIRED and must say: (1) the camera framing and angle; (2) who or what is visible and where in the frame; (3) where in the source shot's camera move the frame sits (e.g. "midway through the push-in, before the pan"); (4) how this shot uses it. Name the same subjects the source shot's prompt names. The source must be an earlier shot (never the shot itself, never a later one); the user generates the source shot first, then picks the exact frame in the app, so "atSec" is only where the picker starts. Example: "references": [{ "frameOf": "s1", "atSec": 2.5, "role": "start", "frameDesc": "Medium close-up, eye level: the man sits centre-left at the computer looking down at the objects on the desk; midway through shot s1's push-in, before the pan to the second person; used as the start frame of this shot." }].` },
  { key: "clip-centric", text: `Schema ${SCHEMA_VERSION}, clip-centric: write "schemaVersion": "${SCHEMA_VERSION}" and keep everything that makes a clip on a "video" asset, its clip: the generation "prompt" (with its "References:" block), "references" (including frameOf entries, RULE 50, and "end-frame"), "genDurationSec", "keyframe", "camera" and the clip's "qa". Wherever another rule speaks of a shot's prompt, references, assets, keyframe or genDurationSec, write it on that shot's clip. A shot never has a "prompt": it is { "id", "title", "description", "durationSec", "clip": "<video asset id>", "inSec"? } plus its layers, dialogue, captions, effects and edit checks. Give each AI shot its own clip (id "<shot id>-clip", name "Clip · <shot title>"); to reuse one generation (the same take seen twice, a wide shot cut into two parts) point several shots at the SAME clip and set each one's "inSec" (seconds into the clip) and "durationSec", and give the clip a "genDurationSec" long enough for every part. The first shot that uses a clip generates it; later shots only trim it. Example: "assets": [ { "id": "s1-clip", "name": "Clip · The climb", "type": "video", "prompt": "References:\\nImage 1 (Rider): reference only, not a frame: keep this identity.\\n\\nThe rider climbs the last stretch …", "references": ["rider"], "genDurationSec": 8, "camera": "Side tracking shot", "qa": ["The rider matches the reference"] } ], "shots": [ { "id": "s1", "title": "The climb", "durationSec": 4, "clip": "s1-clip" }, { "id": "s3", "title": "The climb, later", "durationSec": 3, "clip": "s1-clip", "inSec": 5 } ]. A storyboard without "schemaVersion" is 3.0 (prompts on shots); the app migrates it, but never write that form.` },
];
export const RULES: readonly string[] = RULE_LIST.map((r) => r.text);
/** 1-based public number of a rule, by key. */
export function ruleNumber(key: string): number {
  const i = RULE_LIST.findIndex((r) => r.key === key);
  if (i < 0) throw new Error(`Unknown rule "${key}"`);
  return i + 1;
}
export const rulesSection = () => RULES.map((r, i) => `${i + 1}. ${r}`).join("\n");

/** HOW IT WORKS, FORMAT, CHOOSING PRESETS, PRESETS, RULES and EXAMPLE; `heading` formats each section title (plain caps in the prompt, `##` in markdown). */
export function guideSections(heading: (title: string) => string): string {
  return [
    `${heading("HOW IT WORKS")}\n${HOW_IT_WORKS}`,
    `${heading(`FORMAT ("${STORYBOARD_FORMAT}", v${FORMAT_REVISION})`)}\n\`\`\`\n${FORMAT_SECTION()}\n\`\`\``,
    `${heading("CHOOSING PRESETS")}\n${CHOOSING_PRESETS}`,
    `${heading("PRESETS")}\n${presetsSection()}`,
    `${heading("RULES")}\n${rulesSection()}`,
    `${heading("EXAMPLE")}\n\`\`\`json\n${exampleStoryboardJson()}\n\`\`\``,
  ].join("\n\n");
}

const ROLE = "You are a storyboard planner for AI video production. We have agreed a story together. Turn it into a production storyboard for the Dionysus video editor. Every prompt you write must stand alone: each asset and clip may be made by a different AI agent or chat that sees only that prompt and its images, so repeat the identity, style and references in each one";

/** Full prompt: the whole guide inlined. Works with any AI, including ones that can't open links. */
export function storyboardSystemPrompt(series?: Series): string {
  return `${ROLE} and reply with ONLY one JSON code block in the exact format below — no commentary before or after.

${guideSections((t) => t)}
${seriesBlock(series)}
Now write the storyboard JSON for our story.`;
}

/** P5: the SERIES ASSETS section added to both prompts when the project is an episode of a Series. */
function seriesBlock(series?: Series): string {
  return series ? `\nSERIES ASSETS\n${seriesPromptSection(series)}\n` : "";
}

/** Short prompt: links to the published guide; the AI asks for the full prompt when it can't open links. */
export function storyboardShortPrompt(links: AiLinks = runtimeAiLinks(), series?: Series): string {
  return `${ROLE}.

1. First read the storyboard guide: ${links.guide}
   It explains how the format works and defines the JSON ("${STORYBOARD_FORMAT}", v${FORMAT_REVISION}), how to choose presets, the preset ids you may use, the numbered rules and an example. Follow it exactly. (Same guide as a web page: ${links.guideHtml} · presets as JSON: ${links.presets})
2. If you can't open links, don't guess the format. Reply only: "I can't open the guide — please paste the full Dionysus prompt." The user will then paste it (Dionysus → Storyboard → AI prompt → Full prompt).
3. "durationSec" is the planned on-screen length of the shot in the edit, not what the video model can render. If the model must render longer (e.g. 6 s minimum), keep "durationSec" at the planned length and put the length to generate in "genDurationSec" (e.g. "durationSec": 4, "genDurationSec": 6).
4. Otherwise reply with ONLY one JSON code block containing the storyboard for our story — no commentary before or after.${series ? `\n${seriesBlock(series)}` : ""}`;
}
